import React, { useState } from "react";
import AchievementsPanel from "./AchievementsPanel";
import UserProfileCard from "./UserProfileCard";

export default function AdminDashboard({ reports, token, setMsg }) {
  const [ngos, setNgos] = useState(null);
  const [events, setEvents] = useState(null);
  const [eventStats, setEventStats] = useState(null);
  const [mostActive, setMostActive] = useState(null);

  const API = process.env.REACT_APP_API || "http://localhost:4000";

  const clearAll = () => {
    setNgos(null);
    setEvents(null);
    setEventStats(null);
    setMostActive(null);
  };

  const loadData = async (endpoint, setter, field, errMsg) => {
    if (!token) return setMsg("Login as admin first");
    clearAll();

    try {
      const res = await fetch(`${API}${endpoint}`, {
        headers: { Authorization: `Bearer ${token}` },
      });

      if (!res.ok) throw new Error(errMsg);
      setter((await res.json())[field] || []);
    } catch (err) {
      setMsg(err.message);
    }
  };

  const loadMostActive = async () => {
    if (!token) return setMsg("Login as admin first");
    clearAll();

    try {
      const res = await fetch(`${API}/api/actions/most-active-ngo`, {
        headers: { Authorization: `Bearer ${token}` },
      });

      if (!res.ok) throw new Error("Failed to load most active NGO");
      setMostActive((await res.json()).top || null);
    } catch (err) {
      setMsg(err.message);
    }
  };

  const deleteNgo = async (id) => {
    if (!token) return setMsg("Login as admin first");
    if (!window.confirm("Are you sure you want to remove this NGO?")) return;

    try {
      const res = await fetch(`${API}/api/actions/remove-ngo/${id}`, {
        method: "DELETE",
        headers: { Authorization: `Bearer ${token}` },
      });

      if (!res.ok) throw new Error("Failed to delete NGO");
      setMsg("NGO removed successfully");
      setNgos((prev) => prev.filter((n) => n.id !== id));
    } catch (err) {
      setMsg(err.message);
    }
  };

  const card = {
    padding: 8,
    background: "#fff",
    borderRadius: 8,
    marginBottom: 8,
  };

  return (
    <div style={{ display: "flex", gap: 16, alignItems: "flex-start" }}>

      {/* LEFT PANEL */}
      <div style={{ width: 320, flexShrink: 0 }}>
        <AchievementsPanel
          token={token}
          me={{ points: reports?.adminPoints || 0 }}
          role="user"
          setMsg={setMsg}
        />
      </div>

      {/* MIDDLE PANEL */}
      <div style={{ flex: 1 }}>

        {/* HEADER */}
        <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
          <img
            src="https://cdn-icons-png.flaticon.com/512/9131/9131529.png"
            style={{ width: 40, height: 40 }}
            alt=""
          />
          <h2 style={{ margin: 0 }}>Admin Dashboard</h2>
        </div>

        {/* ⭐ PROFILE MOVED HERE ⭐ */}
        <div style={{ marginTop: 15 }}>
          <UserProfileCard token={token} setMsg={setMsg} />
        </div>

        {/* REPORTS */}
        <h3 style={{ marginTop: 16 }}>Admin Reports</h3>
        <div className="cards">
          <div className="stat-card">
            <div className="stat-num">
              {reports?.donations
                ? reports.donations.reduce(
                    (sum, d) => sum + parseFloat(d.amount || 0),
                    0
                  )
                : "-"}
            </div>
            <div className="stat-label">Total Donation Amount (₹)</div>
          </div>

          <div className="stat-card">
            <div className="stat-num">{reports?.volunteers?.length || 0}</div>
            <div className="stat-label">Total Volunteers</div>
          </div>

          <div className="stat-card">
            <div className="stat-num">{reports?.feedbacks?.length || 0}</div>
            <div className="stat-label">Feedbacks</div>
          </div>
        </div>

        {/* ACTION BUTTONS */}
        <div style={{ marginTop: 15, display: "flex", gap: 12 }}>
          <button onClick={() => loadData("/api/actions/ngos", setNgos, "ngos", "Failed to load NGOs")}>
            View NGOs
          </button>

          <button onClick={() => loadData("/api/actions/registered-events", setEvents, "events", "Failed to load events")}>
            View Events
          </button>

          <button onClick={() => loadData("/api/actions/event-stats", setEventStats, "events", "Failed to load stats")}>
            View Stats
          </button>
        </div>

        {/* EVENTS */}
        {events && (
          <div style={{ marginTop: 20 }}>
            <h4>Registered Events</h4>
            {events.length ? (
              events.map((e) => (
                <div style={card} key={e.id}>
                  <strong>{e.title}</strong>
                  <div style={{ fontSize: 13, color: "#666" }}>{e.date}</div>
                </div>
              ))
            ) : (
              <p>No events registered.</p>
            )}
          </div>
        )}

        {/* EVENT STATS + TOP LISTS */}
        {eventStats && (
          <div style={{ marginTop: 20 }}>
            <h4>Event Statistics</h4>
            {eventStats.length ? (
              eventStats.map((ev) => (
                <div key={ev.id} style={{ ...card, display: "flex", gap: 12 }}>
                  <img
                    src={ev.image_url || "https://via.placeholder.com/120x80"}
                    style={{ width: 100, height: 64, borderRadius: 6, objectFit: "cover" }}
                    alt=""
                  />
                  <div>
                    <div style={{ fontWeight: 600 }}>{ev.title}</div>
                    <div style={{ fontSize: 13, color: "#666" }}>
                      Volunteers: {ev.volunteers_count} — Donations: ₹{ev.donations_sum}
                    </div>
                  </div>
                </div>
              ))
            ) : (
              <p>No event statistics loaded.</p>
            )}
          </div>
        )}

        {/* NGOs */}
        {ngos && (
          <div style={{ marginTop: 20 }}>
            <h4>Registered NGOs</h4>
            {ngos.length ? (
              ngos.map((n) => (
                <div key={n.id} style={{ ...card, display: "flex", justifyContent: "space-between" }}>
                  <div>
                    <strong>{n.name}</strong>
                    <div style={{ fontSize: 13, color: "#666" }}>{n.email}</div>
                  </div>

                  <button
                    style={{ padding: "6px 12px", background: "red", color: "white", borderRadius: 6 }}
                    onClick={() => deleteNgo(n.id)}
                  >
                    Remove
                  </button>
                </div>
              ))
            ) : (
              <p>No NGOs registered.</p>
            )}
          </div>
        )}
      </div>

      {/* RIGHT PANEL */}
      <div style={{ width: 280, flexShrink: 0, position: "sticky", top: 16 }}>
        <div style={{ background: "#fff", padding: 12, borderRadius: 10, boxShadow: "0 6px 20px rgba(2,6,23,0.04)" }}>
          <h4>Quick Actions</h4>

          <button
            onClick={() => loadData("/api/actions/top-volunteers", setEventStats, "top", "Failed to load top volunteers")}
            style={{ width: "100%", padding: 10, borderRadius: 8, marginBottom: 8 }}
          >
            Top Volunteer
          </button>

          <button
            onClick={() => loadData("/api/actions/top-donors", setEventStats, "top", "Failed to load top donors")}
            style={{ width: "100%", padding: 10, borderRadius: 8, marginBottom: 8 }}
          >
            Top Donor
          </button>

          <button
            onClick={() => loadData("/api/actions/badges", setEventStats, "badges", "Failed to load badges")}
            style={{ width: "100%", padding: 10, borderRadius: 8 }}
          >
            View Badges
          </button>
        </div>

        {/* MOST ACTIVE NGO */}
        <div style={{ background: "#fff", marginTop: 20, padding: 12, borderRadius: 10, boxShadow: "0 6px 20px rgba(2,6,23,0.04)" }}>
          <h4>Most Active NGO</h4>
          <button onClick={loadMostActive} style={{ marginTop: 8, padding: 8, width: "100%", borderRadius: 6 }}>
            Load Most Active NGO
          </button>
          {mostActive && (
            <div style={{ marginTop: 12 }}>
              <strong>{mostActive.name}</strong>
              <div style={{ fontSize: 13, color: "#666" }}>Activity Score: {mostActive.activity_score}</div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}
